#include "host.h"
#include "diagnostic_cs.h"     // generated by DXC: d4r_diagnostic_cs
#include <windows.h>
#include <cstdio>
#include <cstring>
#include <stdexcept>

namespace d4r::dx {
namespace {
constexpr UINT DescriptorsPerSlot = 4;     // color SRV, output UAV, history UAV, next-history UAV
constexpr UINT ConstantStride = D3D12_CONSTANT_BUFFER_DATA_PLACEMENT_ALIGNMENT;
constexpr DXGI_FORMAT Format = DXGI_FORMAT_R16G16B16A16_FLOAT;
struct Constants { uint32_t origin[2], size[2]; float scale; uint32_t reset, unused[2]; };

void check(HRESULT hr, const char* operation)
{
    if (FAILED(hr)) {
        char error[256];
        std::snprintf(error, sizeof(error), "%s: HRESULT 0x%08lx", operation, static_cast<unsigned long>(hr));
        throw std::runtime_error(error);
    }
}
#define CK(call) check((call), #call)

D3D12_HEAP_PROPERTIES heap(D3D12_HEAP_TYPE type)
{
    D3D12_HEAP_PROPERTIES properties{}; properties.Type = type;
    properties.CreationNodeMask = properties.VisibleNodeMask = 1;
    return properties;
}
void uavBarrier(ID3D12GraphicsCommandList* list)
{
    D3D12_RESOURCE_BARRIER barrier{}; barrier.Type = D3D12_RESOURCE_BARRIER_TYPE_UAV;
    list->ResourceBarrier(1, &barrier);
}
bool texture(ID3D12Resource* resource, D3D12_RESOURCE_DESC* desc)
{
    if (!resource) return false;
    *desc = resource->GetDesc();
    return desc->Dimension == D3D12_RESOURCE_DIMENSION_TEXTURE2D && desc->Format == Format &&
           desc->DepthOrArraySize == 1 && desc->SampleDesc.Count == 1;
}
}

const char* statusName(Status status)
{
    switch (status) {
    case Status::ok: return "ok";
    case Status::busy: return "busy";
    case Status::pending: return "pending";
    case Status::invalid: return "invalid";
    case Status::deviceLost: return "device lost";
    }
    return "unknown";
}

std::unique_ptr<Backend> Backend::create(ID3D12Device* device, std::string* reason)
{
    try {
        if (!device) throw std::runtime_error("no device");
        D3D12_FEATURE_DATA_D3D12_OPTIONS options{};
        CK(device->CheckFeatureSupport(D3D12_FEATURE_D3D12_OPTIONS, &options, sizeof(options)));
        D3D12_FEATURE_DATA_FORMAT_SUPPORT format{Format};
        CK(device->CheckFeatureSupport(D3D12_FEATURE_FORMAT_SUPPORT, &format, sizeof(format)));
        if (!options.TypedUAVLoadAdditionalFormats || !(format.Support2 & D3D12_FORMAT_SUPPORT2_UAV_TYPED_LOAD) ||
            !(format.Support2 & D3D12_FORMAT_SUPPORT2_UAV_TYPED_STORE))
            throw std::runtime_error("typed R16G16B16A16_FLOAT UAV loads and stores are required");
        std::unique_ptr<Backend> b(new Backend);
        b->device = device;
        b->increment = device->GetDescriptorHandleIncrementSize(D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV);
        D3D12_DESCRIPTOR_RANGE ranges[2]{};
        ranges[0] = {D3D12_DESCRIPTOR_RANGE_TYPE_SRV, 1, 0, 0, 0};
        ranges[1] = {D3D12_DESCRIPTOR_RANGE_TYPE_UAV, 3, 0, 0, 1};
        D3D12_ROOT_PARAMETER parameters[2]{};
        parameters[0].ParameterType = D3D12_ROOT_PARAMETER_TYPE_CBV;
        parameters[0].Descriptor = {0, 0};
        parameters[1].ParameterType = D3D12_ROOT_PARAMETER_TYPE_DESCRIPTOR_TABLE;
        parameters[1].DescriptorTable = {2, ranges};
        D3D12_ROOT_SIGNATURE_DESC rootDesc{}; rootDesc.NumParameters = 2; rootDesc.pParameters = parameters;
        ComPtr<ID3DBlob> blob, error;
        const HRESULT serialized = D3D12SerializeRootSignature(&rootDesc, D3D_ROOT_SIGNATURE_VERSION_1, &blob, &error);
        if (FAILED(serialized) && error) throw std::runtime_error(static_cast<const char*>(error->GetBufferPointer()));
        CK(serialized);
        CK(device->CreateRootSignature(0, blob->GetBufferPointer(), blob->GetBufferSize(), IID_PPV_ARGS(&b->root)));
        D3D12_COMPUTE_PIPELINE_STATE_DESC ps{}; ps.pRootSignature = b->root.Get();
        ps.CS = {d4r_diagnostic_cs, sizeof(d4r_diagnostic_cs)};
        CK(device->CreateComputePipelineState(&ps, IID_PPV_ARGS(&b->pipeline)));
        return b;
    } catch (const std::exception& e) {
        if (reason) *reason = e.what();
        return nullptr;
    }
}

Backend::~Backend()
{
    // Shutdown is the only place that waits on the CPU; per-frame paths never do.
    HANDLE event = CreateEventW(nullptr, FALSE, FALSE, nullptr);
    for (auto& f : owned)
        for (auto& s : f->slots)
            if (s.state == Feature::Slot::submitted && !lost() && event &&
                SUCCEEDED(s.fence->SetEventOnCompletion(s.value, event)))
                WaitForSingleObject(event, 10000);
    if (event) CloseHandle(event);
}

bool Backend::lost()
{
    if (!removed && FAILED(device->GetDeviceRemovedReason())) removed = true;
    return removed;
}

Status Backend::createFeature(const FeatureDesc& desc, Feature** feature)
{
    if (!feature) return Status::invalid;
    *feature = nullptr;
    if (lost()) return Status::deviceLost;
    if (!desc.maxWidth || !desc.maxHeight || desc.maxWidth > 16384 || desc.maxHeight > 16384 ||
        !desc.frameSlots || desc.frameSlots > 16) return Status::invalid;
    collect();
    try {
        std::unique_ptr<Feature> f(new Feature(*this, desc));
        *feature = f.get();
        owned.push_back(std::move(f));
        return Status::ok;
    } catch (const std::exception&) {
        return lost() ? Status::deviceLost : Status::invalid;
    }
}

void Backend::release(Feature* feature)
{
    for (auto& f : owned) if (f.get() == feature) f->released = true;
    collect();
}

void Backend::collect()
{
    const bool gone = lost();
    for (auto it = owned.begin(); it != owned.end();) {
        Feature& f = **it;
        if (f.released) f.retire();
        // A removed device never executes queued work, and its fences report completion.
        if (f.released && (gone || f.inFlight() == 0)) it = owned.erase(it);
        else ++it;
    }
}

size_t Backend::pendingReleases() const
{
    size_t n = 0;
    for (auto& f : owned) n += f->released;
    return n;
}

Feature::Feature(Backend& b, const FeatureDesc& d) : backend(b), desc(d), slots(d.frameSlots)
{
    ID3D12Device* device = backend.device.Get();
    // Everything per-feature is allocated here, at creation, sized for the maximum resolution.
    D3D12_RESOURCE_DESC t{};
    t.Dimension = D3D12_RESOURCE_DIMENSION_TEXTURE2D; t.Width = d.maxWidth; t.Height = d.maxHeight;
    t.DepthOrArraySize = t.MipLevels = 1; t.Format = Format; t.SampleDesc.Count = 1;
    t.Flags = D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS;
    const auto defaultHeap = heap(D3D12_HEAP_TYPE_DEFAULT);
    for (auto& h : history)
        CK(device->CreateCommittedResource(&defaultHeap, D3D12_HEAP_FLAG_NONE, &t, D3D12_RESOURCE_STATE_UNORDERED_ACCESS,
                                           nullptr, IID_PPV_ARGS(&h)));
    D3D12_RESOURCE_DESC c{};
    c.Dimension = D3D12_RESOURCE_DIMENSION_BUFFER; c.Width = UINT64(ConstantStride) * d.frameSlots;
    c.Height = c.DepthOrArraySize = c.MipLevels = 1; c.SampleDesc.Count = 1; c.Layout = D3D12_TEXTURE_LAYOUT_ROW_MAJOR;
    const auto uploadHeap = heap(D3D12_HEAP_TYPE_UPLOAD);
    CK(device->CreateCommittedResource(&uploadHeap, D3D12_HEAP_FLAG_NONE, &c, D3D12_RESOURCE_STATE_GENERIC_READ,
                                       nullptr, IID_PPV_ARGS(&constants)));
    const D3D12_RANGE none{0, 0};
    void* pointer = nullptr; CK(constants->Map(0, &none, &pointer)); mapped = static_cast<uint8_t*>(pointer);
    D3D12_DESCRIPTOR_HEAP_DESC h{};
    h.Type = D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV; h.NumDescriptors = DescriptorsPerSlot * d.frameSlots;
    h.Flags = D3D12_DESCRIPTOR_HEAP_FLAG_SHADER_VISIBLE;
    CK(device->CreateDescriptorHeap(&h, IID_PPV_ARGS(&descriptors)));
}

void Feature::retire()
{
    for (auto& s : slots)
        if (s.state == Slot::submitted && s.fence->GetCompletedValue() >= s.value) {
            s.state = Slot::free; s.fence.Reset(); s.color.Reset(); s.output.Reset();
        }
}

size_t Feature::inFlight() const
{
    size_t n = 0;
    for (auto& s : slots) n += s.state != Slot::free;
    return n;
}

Feature::Slot* Feature::find(const Ticket& ticket, Slot::State state)
{
    if (ticket.slot >= slots.size()) return nullptr;
    Slot& s = slots[ticket.slot];
    return s.state == state && s.serial == ticket.serial ? &s : nullptr;
}

Status Feature::record(ID3D12GraphicsCommandList* list, const FrameDesc& frame, Ticket* ticket)
{
    if (backend.lost()) return Status::deviceLost;
    if (released || !list || !ticket) return Status::invalid;
    D3D12_RESOURCE_DESC color{}, output{};
    if (!texture(frame.color, &color) || !texture(frame.output, &output) || !frame.width || !frame.height ||
        frame.width > desc.maxWidth || frame.height > desc.maxHeight ||
        color.Width < frame.width || color.Height < frame.height ||
        UINT64(frame.x) + frame.width > output.Width || UINT64(frame.y) + frame.height > output.Height ||
        !(output.Flags & D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS))
        return Status::invalid;
    if (pending) return Status::pending;
    retire();
    uint32_t index = 0;
    while (index < slots.size() && slots[index].state != Slot::free) ++index;
    if (index == slots.size()) return Status::busy;

    ID3D12Device* device = backend.device.Get();
    auto cpu = descriptors->GetCPUDescriptorHandleForHeapStart();
    cpu.ptr += SIZE_T(index) * DescriptorsPerSlot * backend.increment;
    D3D12_SHADER_RESOURCE_VIEW_DESC srv{};
    srv.Format = Format; srv.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D; srv.Texture2D.MipLevels = 1;
    srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
    device->CreateShaderResourceView(frame.color, &srv, cpu);
    D3D12_UNORDERED_ACCESS_VIEW_DESC uav{}; uav.Format = Format; uav.ViewDimension = D3D12_UAV_DIMENSION_TEXTURE2D;
    ID3D12Resource* views[3] = {frame.output, history[current].Get(), history[current ^ 1].Get()};
    for (ID3D12Resource* view : views) {
        cpu.ptr += backend.increment;
        device->CreateUnorderedAccessView(view, nullptr, &uav, cpu);
    }
    const Constants k{{frame.x, frame.y}, {frame.width, frame.height}, frame.scale, frame.reset || !historyValid, {0, 0}};
    std::memcpy(mapped + size_t(index) * ConstantStride, &k, sizeof(k));

    // The caller's descriptor heaps, root signature and pipeline are not preserved (see host-contract.md).
    uavBarrier(list);       // previous work on history and output, in this list or an earlier one
    ID3D12DescriptorHeap* heaps[] = {descriptors.Get()};
    list->SetDescriptorHeaps(1, heaps);
    list->SetComputeRootSignature(backend.root.Get());
    list->SetPipelineState(backend.pipeline.Get());
    list->SetComputeRootConstantBufferView(0, constants->GetGPUVirtualAddress() + UINT64(index) * ConstantStride);
    auto gpu = descriptors->GetGPUDescriptorHandleForHeapStart();
    gpu.ptr += UINT64(index) * DescriptorsPerSlot * backend.increment;
    list->SetComputeRootDescriptorTable(1, gpu);
    list->Dispatch((frame.width + 7) / 8, (frame.height + 7) / 8, 1);
    uavBarrier(list);       // the result is complete before later work in the caller's list

    Slot& s = slots[index];
    s.state = Slot::recorded; s.serial = ++serial; s.color = frame.color; s.output = frame.output;
    pending = true;
    *ticket = {index, s.serial};
    return Status::ok;
}

Status Feature::submitted(const Ticket& ticket, ID3D12Fence* f, uint64_t value)
{
    Slot* s = find(ticket, Slot::recorded);
    if (!s || !f || value <= lastValue || (fence && fence.Get() != f)) return Status::invalid;
    fence = f; lastValue = value;
    s->state = Slot::submitted; s->fence = f; s->value = value;
    current ^= 1; historyValid = true; pending = false;
    return Status::ok;
}

Status Feature::discarded(const Ticket& ticket)
{
    Slot* s = find(ticket, Slot::recorded);
    if (!s) return Status::invalid;
    s->state = Slot::free; s->color.Reset(); s->output.Reset();
    pending = false;
    return Status::ok;
}
}
